CREATE TABLE IF NOT EXISTS projects (id BIGSERIAL PRIMARY KEY,name VARCHAR(200) NOT NULL,code VARCHAR(50) UNIQUE,status VARCHAR(30) NOT NULL DEFAULT 'active',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS project_phases (id BIGSERIAL PRIMARY KEY,project_id BIGINT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,phase VARCHAR(30) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'pending',planned_start DATE,planned_end DATE,actual_start DATE,actual_end DATE,UNIQUE(project_id,phase));
